// const — cannot be reassigned (use by default)
const name = 'KERNAL';
const year = 2026;
const isOnline = true;

// let — can be reassigned
let score = 0;
score = score + 10;  // OK
score += 10;         // shorthand

// var — AVOID in modern code
var old = 'do not use';  // has confusing function scope and hoisting

// Naming conventions
const firstName = 'Prashant';   // camelCase (standard JS)
const MAX_SIZE = 100;           // UPPER_SNAKE_CASE for constants
const UserProfile = {};         // PascalCase for classes/constructors

// String — text in single, double, or backtick quotes
const greeting  = 'Hello';
const html      = "<h1>Title</h1>";
const template  = `Hello, ${name}!`;  // template literal

// Number — integers and decimals (one type for both)
const age   = 25;
const pi    = 3.14159;
const big   = 1_000_000;  // underscores for readability

// Boolean — true or false only
const isDone  = false;
const isReady = true;

// null — intentionally empty (you set this)
const user = null;

// undefined — declared but not assigned (JS sets this)
let unset;
console.log(unset);  // undefined

// Object — key-value pairs (covered in a later lesson)
const person = { name: 'Prashant', age: 27 };

// Array — ordered list (technically an object)
const techs = ['HTML', 'CSS', 'JavaScript'];
